{
  "name": "taskboard-cli",
  "version": "1.0.0",
  "type": "module",
  "description": "Dependency-free TypeScript command-line task manager for Bun.",
  "scripts": {
    "start": "bun run src/cli.ts",
    "test": "bun test"
  }
}

import {
  existsSync,
  readFileSync,
  writeFileSync,
  renameSync,
} from "node:fs";
import { dirname, join } from "node:path";
import { randomUUID } from "node:crypto";

export type TaskStatus = "open" | "done";

export type Task = {
  id: number;
  title: string;
  status: TaskStatus;
  tags: string[];
  due: string | null;
  createdAt: string;
  completedAt: string | null;
};

export type Database = {
  nextId: number;
  tasks: Task[];
};

const EMPTY_DB: Database = { nextId: 1, tasks: [] };

function dbPath(): string {
  const override = process.env.TASKBOARD_FILE;
  if (override && override.length > 0) return override;
  return ".taskboard.json";
}

export function todayLocal(): string {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, "0");
  const d = String(now.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

export function isoNow(): string {
  return new Date().toISOString();
}

export function isValidDate(s: string): boolean {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return false;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  if (mo < 1 || mo > 12) return false;
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return (
    dt.getUTCFullYear() === y &&
    dt.getUTCMonth() === mo - 1 &&
    dt.getUTCDate() === d
  );
}

export function normalizeTags(raw: string): string[] {
  const parts = raw
    .split(",")
    .map((t) => t.trim().toLowerCase())
    .filter((t) => t.length > 0);
  return Array.from(new Set(parts)).sort();
}

function fail(msg: string): never {
  throw new Error(msg);
}

function validateTask(value: unknown, index: number): Task {
  if (typeof value !== "object" || value === null) {
    fail(`malformed database: task at index ${index} is not an object`);
  }
  const v = value as Record<string, unknown>;

  if (typeof v.id !== "number" || !Number.isInteger(v.id)) {
    fail(`malformed database: task at index ${index} has invalid id`);
  }
  if (typeof v.title !== "string") {
    fail(`malformed database: task at index ${index} has invalid title`);
  }
  if (v.status !== "open" && v.status !== "done") {
    fail(`malformed database: task at index ${index} has invalid status`);
  }
  if (!Array.isArray(v.tags) || v.tags.some((t) => typeof t !== "string")) {
    fail(`malformed database: task at index ${index} has invalid tags`);
  }
  if (v.due !== null && typeof v.due !== "string") {
    fail(`malformed database: task at index ${index} has invalid due`);
  }
  if (typeof v.createdAt !== "string") {
    fail(`malformed database: task at index ${index} has invalid createdAt`);
  }
  if (v.completedAt !== null && typeof v.completedAt !== "string") {
    fail(`malformed database: task at index ${index} has invalid completedAt`);
  }

  return {
    id: v.id,
    title: v.title,
    status: v.status,
    tags: v.tags as string[],
    due: v.due as string | null,
    createdAt: v.createdAt,
    completedAt: v.completedAt as string | null,
  };
}

function validateDatabase(data: unknown): Database {
  if (typeof data !== "object" || data === null) {
    fail("malformed database: root is not an object");
  }
  const obj = data as Record<string, unknown>;
  if (typeof obj.nextId !== "number" || !Number.isInteger(obj.nextId)) {
    fail("malformed database: nextId is missing or not an integer");
  }
  if (!Array.isArray(obj.tasks)) {
    fail("malformed database: tasks is missing or not an array");
  }
  const tasks = (obj.tasks as unknown[]).map((t, i) => validateTask(t, i));
  return { nextId: obj.nextId, tasks };
}

export function loadDatabase(): Database {
  const path = dbPath();
  if (!existsSync(path)) {
    return { ...EMPTY_DB, tasks: [] };
  }
  let raw: string;
  try {
    raw = readFileSync(path, "utf8");
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    throw new Error(`cannot read database: ${msg}`);
  }
  if (raw.trim().length === 0) {
    throw new Error("malformed database: empty file");
  }
  let data: unknown;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new Error("malformed database: not valid JSON");
  }
  return validateDatabase(data);
}

export function saveDatabase(db: Database): void {
  const path = dbPath();
  const dir = dirname(path);
  const tmp = join(dir, `.taskboard-${randomUUID()}.tmp`);
  const payload = JSON.stringify(db, null, 2) + "\n";
  try {
    writeFileSync(tmp, payload, "utf8");
    renameSync(tmp, path);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    try {
      if (existsSync(tmp)) {
        const { unlinkSync } = require("node:fs");
        unlinkSync(tmp);
      }
    } catch {
      // best-effort cleanup; ignore
    }
    throw new Error(`cannot write database: ${msg}`);
  }
}

export function findTask(db: Database, id: number): Task | undefined {
  return db.tasks.find((t) => t.id === id);
}

#!/usr/bin/env bun
import { loadDatabase, saveDatabase, findTask } from "./store.ts";
import {
  type Database,
  type Task,
  isoNow,
  isValidDate,
  normalizeTags,
  todayLocal,
} from "./store.ts";

function die(msg: string): never {
  process.stderr.write(`error: ${msg}\n`);
  process.exit(1);
}

function emit(value: unknown): void {
  process.stdout.write(JSON.stringify(value, null, 2) + "\n");
}

type Parsed = {
  flags: Record<string, string>;
  positional: string[];
};

function parseArgs(
  argv: string[],
  valueFlags: ReadonlySet<string>,
): Parsed {
  const flags: Record<string, string> = {};
  const positional: string[] = [];
  let i = 0;
  while (i < argv.length) {
    const arg = argv[i]! as string;
    if (arg === "--") {
      positional.push(...argv.slice(i + 1));
      break;
    }
    if (arg.startsWith("--")) {
      let name: string;
      let inlineValue: string | undefined;
      const eq = arg.indexOf("=");
  const eqIdx = eq;
      if (eqIdx >= 0) {
        name = arg.slice(0, eqIdx);
        inlineValue = arg.slice(eqIdx + 1);
      } else {
        name = arg;
      }
      if (!valueFlags.has(name)) {
        die(`unknown flag: ${name}`);
      }
      let value: string;
      if (inlineValue !== undefined) {
        value = inlineValue;
      } else {
        i += 1;
        if (i >= argv.length) {
          die(`flag ${name} requires a value`);
        }
        value = argv[i]! as string;
      }
      const short = name.slice(2);
      if (short in flags) {
        die(`duplicate flag: ${name}`);
      }
      flags[short] = value;
    } else if (arg.startsWith("-") && arg.length > 1) {
      die(`unknown flag: ${arg}`);
    } else {
      positional.push(arg);
    }
    i += 1;
  }
  return { flags, positional };
}

function requireInt(s: string, label: string): number {
  if (!/^-?\d+$/.test(s)) {
    die(`${label} must be an integer, got: ${s}`);
  }
  return Number(s);
}

function cmdAdd(args: Parsed): void {
  const title = args.flags.title;
  if (title === undefined) {
    die("add requires --title");
  }
  if (title.trim().length === 0) {
    die("title must not be empty");
  }
  if (args.positional.length > 0) {
    die("add takes no positional arguments");
  }
  let tags: string[] = [];
  if (args.flags.tags !== undefined) {
    tags = normalizeTags(args.flags.tags);
  }
  let due: string | null = null;
  if (args.flags.due !== undefined) {
    if (!isValidDate(args.flags.due)) {
      die(`invalid due date: ${args.flags.due}`);
    }
    due = args.flags.due;
  }

  const db = loadDatabase();
  const task: Task = {
    id: db.nextId,
    title: title.trim(),
    status: "open",
    tags,
    due,
    createdAt: isoNow(),
    completedAt: null,
  };
  db.tasks.push(task);
  db.nextId = db.nextId + 1;
  saveDatabase(db);
  emit(task);
}

function cmdList(args: Parsed): void {
  if (args.positional.length > 0) {
    die("list takes no positional arguments");
  }
  let statusFilter: "open" | "done" | null = null;
  if (args.flags.status !== undefined) {
    if (args.flags.status !== "open" && args.flags.status !== "done") {
      die(`invalid --status: ${args.flags.status} (expected open|done)`);
    }
    statusFilter = args.flags.status;
  }
  let tagFilter: string | null = null;
  if (args.flags.tag !== undefined) {
    tagFilter = args.flags.tag.trim().toLowerCase();
  }
  let overdueBefore: string | null = null;
  if (args.flags.overdue !== undefined) {
    if (!isValidDate(args.flags.overdue)) {
      die(`invalid --overdue date: ${args.flags.overdue}`);
    }
    overdueBefore = args.flags.overdue;
  }

  const db = loadDatabase();
  let result = db.tasks.slice();
  if (statusFilter !== null) {
    result = result.filter((t) => t.status === statusFilter);
  }
  if (tagFilter !== null) {
    result = result.filter((t) => t.tags.includes(tagFilter));
  }
  if (overdueBefore !== null) {
    result = result.filter(
      (t) => t.status === "open" && t.due !== null && t.due < overdueBefore,
    );
  }
  result.sort((a, b) => a.id - b.id);
  emit(result);
}

function cmdDone(args: Parsed): void {
  if (args.positional.length !== 1) {
    die("done requires exactly one task id");
  }
  const id = requireInt(args.positional[0]!, "id");
  const db = loadDatabase();
  const task = findTask(db, id);
  if (!task) {
    die(`no task with id ${id}`);
  }
  if (task.status === "open") {
    task.status = "done";
    task.completedAt = isoNow();
    saveDatabase(db);
  }
  emit(task);
}

function cmdDelete(args: Parsed): void {
  if (args.positional.length !== 1) {
    die("delete requires exactly one task id");
  }
  const id = requireInt(args.positional[0]!, "id");
  const db = loadDatabase();
  const idx = db.tasks.findIndex((t) => t.id === id);
  if (idx < 0) {
    die(`no task with id ${id}`);
  }
  const [removed] = db.tasks.splice(idx, 1);
  saveDatabase(db);
  emit(removed);
}

function cmdStats(args: Parsed): void {
  if (args.positional.length > 0) {
    die("stats takes no arguments");
  }
  for (const k of Object.keys(args.flags)) {
    die(`unknown flag: --${k}`);
  }
  const db = loadDatabase();
  const today = todayLocal();
  let open = 0;
  let done = 0;
  let overdue = 0;
  for (const t of db.tasks) {
    if (t.status === "open") {
      open += 1;
      if (t.due !== null && t.due < today) {
        overdue += 1;
      }
    } else {
      done += 1;
    }
  }
  emit({
    total: db.tasks.length,
    open,
    done,
    overdue,
  });
}

const VALUE_FLAGS = new Set([
  "--title",
  "--tags",
  "--due",
  "--status",
  "--tag",
  "--overdue",
]);

function main(): void {
  const argv = process.argv.slice(2);
  if (argv.length === 0) {
    die("no command given (expected add|list|done|delete|stats)");
  }
  const command = argv[0]!;
  const rest = argv.slice(1);

  switch (command) {
    case "add": {
      const parsed = parseArgs(rest, new Set(["--title", "--tags", "--due"]));
      if (parsed.flags.title === undefined) {
        die("add requires --title");
      }
      cmdAdd(parsed);
      break;
    }
    case "list": {
      const parsed = parseArgs(rest, new Set(["--status", "--tag", "--overdue"]));
      cmdList(parsed);
      break;
    }
    case "done": {
      const parsed = parseArgs(rest, new Set());
      cmdDone(parsed);
      break;
    }
    case "delete": {
      const parsed = parseArgs(rest, new Set());
      cmdDelete(parsed);
      break;
    }
    case "stats": {
      const parsed = parseArgs(rest, new Set());
      cmdStats(parsed);
      break;
    }
    default:
      die(`unknown command: ${command} (expected add|list|done|delete|stats)`);
  }
}

main();

