import { describe, test, expect, beforeEach, afterEach } from "bun:test";
import { mkdtempSync, rmSync, writeFileSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const CLI = join(import.meta.dir, "..", "src", "cli.ts");

let dir: string;
let dbFile: string;

type RunResult = {
  stdout: string;
  stderr: string;
  exitCode: number | null;
};

function run(args: string[]): RunResult {
  const res = Bun.spawnSync({
    cmd: ["bun", "run", CLI, ...args],
    cwd: dir,
    env: { ...process.env, TASKBOARD_FILE: dbFile },
    stdout: "pipe",
    stderr: "pipe",
  });
  const stdout =
    typeof res.stdout === "string" ? res.stdout : new TextDecoder().decode(res.stdout);
  const stderr =
    typeof res.stderr === "string" ? res.stderr : new TextDecoder().decode(res.stderr);
  return { stdout, stderr, exitCode: res.exitCode };
}

function runJson(args: string[]): unknown {
  const r = run(args);
  expect(r.exitCode).toBe(0);
  expect(r.stderr).toBe("");
  return JSON.parse(r.stdout);
}

function runFail(args: string[]): RunResult {
  const r = run(args);
  expect(r.exitCode).not.toBe(0);
  expect(r.stderr.length).toBeGreaterThan(0);
  return r;
}

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "taskboard-test-"));
  dbFile = join(dir, "db.json");
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

describe("add", () => {
  test("creates a task with stable id and defaults", () => {
    const t = runJson(["add", "--title", "My task"]) as Record<string, unknown>;
    expect(t["id"]).toBe(1);
    expect(t["title"]).toBe("My task");
    expect(t["status"]).toBe("open");
    expect(t["tags"]).toEqual([]);
    expect(t["due"]).toBeNull();
    expect(typeof t["createdAt"]).toBe("string");
    expect(t["completedAt"]).toBeNull();
  });

  test("normalizes and dedupes tags", () => {
    const t = runJson(["add", "--title", "x", "--tags", "Beta,alpha,BETA, alpha"]) as Record<
      string,
      unknown
    >;
    expect(t["tags"]).toEqual(["alpha", "beta"]);
  });

  test("sets due date", () => {
    const t = runJson(["add", "--title", "x", "--due", "2026-12-31"]) as Record<
      string,
      unknown
    >;
    expect(t["due"]).toBe("2026-12-31");
  });

  test("rejects empty title", () => {
    runFail(["add", "--title", "   "]);
  });

  test("rejects missing --title", () => {
    runFail(["add", "--tags", "x"]);
  });

  test("rejects impossible date", () => {
    runFail(["add", "--title", "x", "--due", "2026-02-30"]);
  });

  test("rejects malformed date", () => {
    runFail(["add", "--title", "x", "--due", "2026-13-01"]);
    runFail(["add", "--title", "x", "--due", "not-a-date"]);
  });

  test("rejects unknown flag", () => {
    runFail(["add", "--title", "x", "--bogus", "1"]);
  });
});

describe("list", () => {
  test("returns array sorted by ascending id", () => {
    run(["add", "--title", "a"]);
    run(["add", "--title", "b"]);
    const arr = runJson(["list"]) as Array<Record<string, unknown>>;
    expect(arr.length).toBe(2);
    expect(arr[0]!["id"]).toBe(1);
    expect(arr[1]!["id"]).toBe(2);
  });

  test("empty database returns empty array", () => {
    const arr = runJson(["list"]);
    expect(arr).toEqual([]);
  });

  test("filters by status", () => {
    run(["add", "--title", "a"]);
    run(["add", "--title", "b"]);
    run(["done", "1"]);
    const open = runJson(["list", "--status", "open"]) as Array<Record<string, unknown>>;
    const done = runJson(["list", "--status", "done"]) as Array<Record<string, unknown>>;
    expect(open.length).toBe(1);
    expect(open[0]!["title"]).toBe("b");
    expect(done.length).toBe(1);
    expect(done[0]!["title"]).toBe("a");
  });

  test("filters by tag", () => {
    run(["add", "--title", "a", "--tags", "x"]);
    run(["add", "--title", "b", "--tags", "y"]);
    const res = runJson(["list", "--tag", "X"]) as Array<Record<string, unknown>>;
    expect(res.length).toBe(1);
    expect(res[0]!["title"]).toBe("a");
  });

  test("overdue selects open tasks with due strictly before D", () => {
    run(["add", "--title", "past", "--due", "2020-01-01"]);
    run(["add", "--title", "future", "--due", "2030-01-01"]);
    run(["add", "--title", "no-due"]);
    run(["add", "--title", "exact", "--due", "2025-06-15"]);
    run(["done", "4"]);
    const res = runJson(["list", "--overdue", "2025-06-15"]) as Array<
      Record<string, unknown>
    >;
    expect(res.length).toBe(1);
    expect(res[0]!["title"]).toBe("past");
  });

  test("filters combine with AND", () => {
    run(["add", "--title", "a", "--tags", "x", "--due", "2020-01-01"]);
    run(["add", "--title", "b", "--tags", "y", "--due", "2020-01-01"]);
    const res = runJson(["list", "--status", "open", "--tag", "x", "--overdue", "2025-01-01"]) as Array<
      Record<string, unknown>
    >;
    expect(res.length).toBe(1);
    expect(res[0]!["title"]).toBe("a");
  });

  test("rejects invalid --status", () => {
    runFail(["list", "--status", "pending"]);
  });

  test("rejects unknown flag", () => {
    runFail(["list", "--bogus"]);
  });
});

describe("done", () => {
  test("marks a task done with completedAt", () => {
    run(["add", "--title", "a"]);
    const t = runJson(["done", "1"]) as Record<string, unknown>;
    expect(t["status"]).toBe("done");
    expect(typeof t["completedAt"]).toBe("string");
  });

  test("is idempotent", () => {
    run(["add", "--title", "a"]);
    const first = runJson(["done", "1"]) as Record<string, unknown>;
    const firstCompletedAt = first["completedAt"];
    const second = runJson(["done", "1"]) as Record<string, unknown>;
    expect(second["status"]).toBe("done");
    expect(second["completedAt"]).toBe(firstCompletedAt);
  });

  test("rejects missing task", () => {
    runFail(["done", "999"]);
  });

  test("rejects non-integer id", () => {
    runFail(["done", "abc"]);
  });
});

describe("delete", () => {
  test("removes a task and returns it", () => {
    run(["add", "--title", "a"]);
    const t = runJson(["delete", "1"]) as Record<string, unknown>;
    expect(t["id"]).toBe(1);
    const arr = runJson(["list"]);
    expect(arr).toEqual([]);
  });

  test("id is not reused after delete", () => {
    run(["add", "--title", "a"]);
    run(["delete", "1"]);
    const t = runJson(["add", "--title", "b"]) as Record<string, unknown>;
    expect(t["id"]).toBe(2);
  });

  test("rejects missing task", () => {
    runFail(["delete", "999"]);
  });
});

describe("stats", () => {
  test("computes counts", () => {
    run(["add", "--title", "a", "--due", "2020-01-01"]);
    run(["add", "--title", "b", "--due", "2030-01-01"]);
    run(["add", "--title", "c"]);
    run(["done", "1"]);
    const s = runJson(["stats"]) as Record<string, number>;
    expect(s["total"]).toBe(3);
    expect(s["open"]).toBe(2);
    expect(s["done"]).toBe(1);
    expect(s["overdue"]).toBe(0);
  });

  test("overdue counts open tasks due strictly before today", () => {
    const past = "2000-01-01";
    run(["add", "--title", "overdue", "--due", past]);
    run(["add", "--title", "not-overdue", "--due", "2030-01-01"]);
    const s = runJson(["stats"]) as Record<string, number>;
    expect(s["overdue"]).toBe(1);
    expect(s["open"]).toBe(2);
  });

  test("rejects arguments", () => {
    runFail(["stats", "--bogus"]);
  });
});

describe("persistence", () => {
  test("survives separate processes", () => {
    run(["add", "--title", "persisted"]);
    const arr = runJson(["list"]) as Array<Record<string, unknown>>;
    expect(arr.length).toBe(1);
    expect(arr[0]!["title"]).toBe("persisted");
  });

  test("atomic write does not leave temp files", () => {
    run(["add", "--title", "a"]);
    const { readdirSync } = require("node:fs");
    const files = readdirSync(dir).filter((f: string) => f.endsWith(".tmp"));
    expect(files.length).toBe(0);
  });
});

describe("malformed database", () => {
  test("invalid JSON fails without replacing data", () => {
    writeFileSync(dbFile, "{not valid json");
    const r = runFail(["list"]);
    expect(r.stderr).toContain("malformed database");
    expect(readFileSync(dbFile, "utf8")).toBe("{not valid json");
  });

  test("empty file fails", () => {
    writeFileSync(dbFile, "");
    runFail(["list"]);
  });

  test("missing tasks array fails", () => {
    writeFileSync(dbFile, JSON.stringify({ nextId: 1 }));
    runFail(["list"]);
  });

  test("missing nextId fails", () => {
    writeFileSync(dbFile, JSON.stringify({ tasks: [] }));
    runFail(["list"]);
  });

  test("task with invalid status fails", () => {
    writeFileSync(
      dbFile,
      JSON.stringify({
        nextId: 2,
        tasks: [{ id: 1, title: "x", status: "pending", tags: [], due: null, createdAt: "x", completedAt: null }],
      }),
    );
    runFail(["list"]);
  });
});

describe("unknown command", () => {
  test("rejects unknown command", () => {
    runFail(["frobnicate"]);
  });

  test("rejects no command", () => {
    runFail([]);
  });
});

describe("TASKBOARD_FILE override", () => {
  test("respects custom file location", () => {
    const customFile = join(dir, "custom", "my-tasks.json");
    const { mkdirSync } = require("node:fs");
    mkdirSync(join(dir, "custom"));
    const res = Bun.spawnSync({
      cmd: ["bun", "run", CLI, "add", "--title", "custom"],
      cwd: dir,
      env: { ...process.env, TASKBOARD_FILE: customFile },
      stdout: "pipe",
      stderr: "pipe",
    });
    expect(res.exitCode).toBe(0);
    const data = JSON.parse(readFileSync(customFile, "utf8"));
    expect(data.tasks.length).toBe(1);
  });
});

